static int online_conversation(IDirect3DDevice9 *dev, const char *with, int avatar);   // below (1: a game starts)

// Players: one screen, three tabs (LB/RB) - the friends (online first; then the players one played with lately),
// the players online, the ranking. Each row: the avatar with a dot of where the player is, the name in its chat
// colour and its flag, what it is doing, the connection in a word; a friend waiting in a room of theirs: "Join".
// A the player's statistics, X a message, Y joins that room (else makes the player a friend, or not). Each tab
// read when first shown. Returns 1 when a game starts (a room joined from here).
// rankOnly: the main menu's rankings - only This week and All time (start: which), opaque, this player's row marked.
// ---- The most played games online (the players' screen's "Games" tab): the first three big (box art, place medal, hours,
// players, this player's own time), the rest as rows (a week before: up, down or new). LT/RT the period; A makes a room
// of the one picked when this console has it. Returns -1 left (B), 0 or 1 the tab asked for (LB, RB), 2 a game starts.
#define TOP_COVER_W 216
#define TOP_COVER_H 116
static int online_have_crc1(const std::string &code)   // "NALE / 34EE4749": a ROM of this console with that CRC1
{
    std::map<std::string, RomInfo>::const_iterator it;
    const size_t slash = code.find('/');
    u32 crc1;
    int r = 0;
    if (slash == std::string::npos || !s_detailsEvent) return 0;
    crc1 = (u32)strtoul(code.c_str() + slash + 1, NULL, 16);
    EnterCriticalSection(&s_detailsLock);
    for (it = s_detailsMemo.begin(); it != s_detailsMemo.end() && !r; ++it)
        if (it->second.ok && it->second.crc1 == crc1) r = 1;
    LeaveCriticalSection(&s_detailsLock);
    return r;
}

static int online_create(IDirect3DDevice9 *dev, std::string *file, const char *preset = NULL);   // below
static void home_hours(char *out, size_t size, int seconds);   // with the main menu, below

static int online_top_games(IDirect3DDevice9 *dev, const int *labels, int tabs, int cur)
{
    static const D3DCOLOR medal[3] = { D3DCOLOR_ARGB(255, 255, 196, 70), D3DCOLOR_ARGB(255, 200, 208, 222), D3DCOLOR_ARGB(255, 215, 140, 80) };
    static const char periods[3] = { 'w', 'm', 'a' };
    static const int periodLabel[3] = { T_ONLINE_TAB_WEEK, T_TOP_MONTH, T_TOP_ALL };
    std::vector<OnlineTopGame> games;
    IDirect3DTexture9 *cover[10] = { 0 };
    int coverW[10] = { 0 }, coverH[10] = { 0 }, tried[10] = { 0 };
    int period = 0, loaded = -1, sel = 0, trig = 3, k, result = -1;
    UiInput in;
    UiInputInit(&in);
    for (;;)
    {
        const float w = UI_WIDTH - 2 * UI_SAFE_X, h = 520, x = UI_SAFE_X, y = 112, lx = x + 26, lw = w - 52;
        const int n = (int)games.size();
        WORD down;
        int pressed, loads = 2;
        char t[200], fit[200];
        if (loaded != period)
        {
            online_busy(dev, Tr(T_TOP_TITLE), T_ONLINE_CONNECTING);
            for (k = 0; k < 10; k++) { if (cover[k]) UiImageRelease(dev, cover[k]); cover[k] = NULL; tried[k] = 0; }
            if (!OnlineTopGames(periods[period], &games)) { online_message(dev, Tr(T_TOP_TITLE), online_error_text()); result = -1; break; }
            if (games.size() > 10) games.resize(10);
            loaded = period;
            sel = 0;
            UiInputInit(&in);
            continue;
        }
        down = UiInputPoll(&in);
        pressed = exp_triggers(&trig);
        if (down & (XINPUT_GAMEPAD_B | XINPUT_GAMEPAD_BACK)) { xb_audio_ui_sound(XB_SFX_BACK); result = -1; break; }
        if (down & XINPUT_GAMEPAD_LEFT_SHOULDER) { result = (cur + tabs - 1) % tabs; xb_audio_ui_sound(XB_SFX_TAB); break; }
        if (down & XINPUT_GAMEPAD_RIGHT_SHOULDER) { result = (cur + 1) % tabs; xb_audio_ui_sound(XB_SFX_TAB); break; }
        if (pressed) { period = (period + ((pressed & 2) ? 1 : 2)) % 3; xb_audio_ui_sound(XB_SFX_TAB); continue; }
        if (n)
        {
            // the first three across, the rest down the right
            if (down & XINPUT_GAMEPAD_DPAD_RIGHT) sel = sel < 2 ? sel + 1 : sel < 3 ? 3 : sel;
            if (down & XINPUT_GAMEPAD_DPAD_LEFT) sel = sel > 0 && sel < 3 ? sel - 1 : sel >= 3 ? 2 : sel;
            if (down & XINPUT_GAMEPAD_DPAD_DOWN) sel = sel >= 3 && sel + 1 < n ? sel + 1 : sel;
            if (down & XINPUT_GAMEPAD_DPAD_UP) sel = sel > 3 ? sel - 1 : sel;
            if (sel >= n) sel = n - 1;
            if (down & (XINPUT_GAMEPAD_DPAD_LEFT | XINPUT_GAMEPAD_DPAD_RIGHT | XINPUT_GAMEPAD_DPAD_UP | XINPUT_GAMEPAD_DPAD_DOWN)) xb_audio_ui_sound(XB_SFX_MOVE);
            if ((down & XINPUT_GAMEPAD_A) && online_have_crc1(games[sel].code))
            {
                // A room of this game: its ROM here (by its CRC1), straight to the room's name.
                std::string file, rom;
                const size_t slash = games[sel].code.find('/');
                const u32 crc1 = slash == std::string::npos ? 0 : (u32)strtoul(games[sel].code.c_str() + slash + 1, NULL, 16);
                std::vector<RomEntry> roms;
                size_t r2;
                scan_roms(&roms);
                for (r2 = 0; r2 < roms.size() && rom.empty(); r2++)
                {
                    H64Rom hr;
                    if (read_header(roms[r2].file.c_str(), &hr)) { if (hr.crc1 == crc1) rom = roms[r2].file; h64_rom_free(&hr); }
                }
                if (!rom.empty() && online_create(dev, &file, rom.c_str()) && online_lobby(dev, file)) { result = 2; break; }
                UiInputInit(&in);
                continue;
            }
            else if (down & XINPUT_GAMEPAD_A) xb_audio_ui_sound(XB_SFX_ERROR);
        }
        dev->Clear(0, NULL, D3DCLEAR_TARGET, UI_COL_BG_BOTTOM, 1.0f, 0);
        online_begin(dev, __FUNCTION__);
        hub_frame("", NULL, x, y, w, h);
        UiOnlineLogo(UI_WIDTH * 0.5f, y - 46, 60);
        online_me_corner(x, y, w);
        online_tab_bar(lx, y, Tr(T_ONLINE_USERS), labels, NULL, tabs, cur);
        UiRect(lx, y + 74, lw, 1, UI_COL_LINE);
        // the period, at the right of the title
        {
            float px = lx + lw;
            for (k = 2; k >= 0; k--)
            {
                const float pw = UiTextWidth(k == period ? UI_BOLD : UI_REGULAR, 15, Tr(periodLabel[k])) + 26;
                px -= pw;
                if (k == period) UiRoundRect(px, y + 90, pw, 28, 14, SEL_HI(235), SEL_LO(235));
                UiText(k == period ? UI_BOLD : UI_REGULAR, 15, px + pw * 0.5f, y + 104, k == period ? UI_COL_TEXT : UI_COL_TEXT2, Tr(periodLabel[k]), UI_CENTER);
                px -= 6;
            }
            UiText(UI_BOLD, 12, px - 4, y + 104, UI_COL_TEXT3, "LT  RT", UI_RIGHT);
        }
        UiText(UI_BOLD, 22, lx, y + 98, UI_COL_TEXT, Tr(T_TOP_TITLE), UI_LEFT);
        UiText(UI_REGULAR, 13, lx, y + 122, UI_COL_TEXT3, Tr(T_TOP_SUB), UI_LEFT);
        if (!n) UiText(UI_REGULAR, 19, lx + lw * 0.5f, y + h * 0.55f, UI_COL_TEXT3, Tr(T_TOP_EMPTY), UI_CENTER);
        for (k = 0; k < n; k++)
        {
            const OnlineTopGame *g = &games[k];
            const int s = k == sel, have = online_have_crc1(g->code);
            if (!tried[k] && loads > 0)
            {
                // its box art when this console has it (by its code's key), a few a frame
                char key[16];
                u8 *rgba = NULL;
                int cw = 0, ch = 0;
                tried[k] = 1;
                loads--;
                if (ArtKeyFromCode(g->game.c_str(), g->code.c_str(), key) && ArtReadCoverKey(key, ART_KIND_BOX, &rgba, &cw, &ch, NULL) && rgba && cw > 0 && ch > 0)
                {
                    u8 *small;
                    h64_image_fit(cw, ch, TOP_COVER_W, TOP_COVER_H, &coverW[k], &coverH[k]);
                    small = h64_image_scale(rgba, cw, ch, coverW[k], coverH[k]);
                    if (small) cover[k] = UiImageCreate(dev, small, coverW[k], coverH[k]);
                    free(small);
                }
                free(rgba);
            }
            if (k < 3)
            {
                // a card: its box art, medal, name and version, hours and players, this player's own time
                const float cx = lx + k * 250, cy = y + 140, cw = 238, ch = 236;
                if (s)
                {
                    selection_glow(cx - 5, cy - 5, cw + 10, ch + 10, 18, selection_pulse());
                    UiRoundRing(cx - 4, cy - 4, cw + 8, ch + 8, 18, 3.0f, SEL_RING(selection_pulse()));
                }
                UiRoundRect(cx, cy, cw, ch, 16, D3DCOLOR_ARGB(s ? 30 : 16, 255, 255, 255), D3DCOLOR_ARGB(s ? 30 : 16, 255, 255, 255));
                UiRoundRing(cx, cy, cw, ch, 16, 1.5f, (medal[k] & 0x00FFFFFF) | 0x70000000);
                UiRoundRect(cx + 11, cy + 11, cw - 22, TOP_COVER_H, 10, D3DCOLOR_ARGB(255, 10, 11, 18), D3DCOLOR_ARGB(255, 8, 9, 14));
                if (cover[k]) cover_draw(cover[k], cx + 11, cy + 11, cw - 22, TOP_COVER_H, 10, D3DCOLOR_ARGB(255, 255, 255, 255), 0);
                UiCircle(cx + 32, cy + 32, 15, medal[k]);
                sprintf(t, "%d", k + 1);
                UiText(UI_BOLD, 16, cx + 32, cy + 32, D3DCOLOR_ARGB(255, 30, 26, 20), t, UI_CENTER);
                online_game_line(cx + 14, cy + 152, cw - 28, 15, NULL, g->game.c_str(), UI_COL_TEXT);
                _snprintf(t, sizeof(t) - 1, Tr(T_TOP_HOURS), (g->minutes + 30) / 60);
                t[sizeof(t) - 1] = 0;
                {
                    const float hw = UiText(UI_BOLD, 22, cx + 14, cy + 186, medal[k], t, UI_LEFT);
                    _snprintf(t, sizeof(t) - 1, Tr(T_TOP_PLAYERS), g->players);
                    t[sizeof(t) - 1] = 0;
                    UiText(UI_REGULAR, 13, cx + 24 + hw, cy + 188, UI_COL_TEXT2, t, UI_LEFT);
                }
                if (g->mine)
                {
                    char hrs[32];
                    home_hours(hrs, sizeof(hrs), g->mine * 60);
                    _snprintf(t, sizeof(t) - 1, Tr(T_TOP_YOU), hrs);
                    t[sizeof(t) - 1] = 0;
                    UiText(UI_BOLD, 12, cx + cw - 14, cy + 216, ONLINE_GREEN, t, UI_RIGHT);
                }
                UiText(UI_REGULAR, 12, cx + 14, cy + 216, have ? ONLINE_GREEN : UI_COL_TEXT3, Tr(have ? T_TOP_HAVE : T_TOP_DONT), UI_LEFT);
            }
            else
            {
                // a row: place, small box art, name and version, players, hours, up or down since a week before
                const float rx = lx + 760, rw = lw - 760, ry = y + 140 + (k - 3) * 56;
                if (s) selection_bar(rx, ry, rw, 48);
                else UiRoundRect(rx, ry, rw, 48, 12, D3DCOLOR_ARGB(12, 255, 255, 255), D3DCOLOR_ARGB(12, 255, 255, 255));
                sprintf(t, "%d", k + 1);
                UiText(UI_BOLD, 16, rx + 18, ry + 24, UI_COL_TEXT2, t, UI_CENTER);
                UiRoundRect(rx + 34, ry + 7, 46, 34, 4, D3DCOLOR_ARGB(255, 10, 11, 18), D3DCOLOR_ARGB(255, 8, 9, 14));
                if (cover[k]) cover_draw(cover[k], rx + 34, ry + 7, 46, 34, 4, D3DCOLOR_ARGB(255, 255, 255, 255), 0);
                online_game_line(rx + 90, ry + 16, rw - 170, 14, NULL, g->game.c_str(), UI_COL_TEXT);
                _snprintf(t, sizeof(t) - 1, Tr(T_TOP_PLAYERS), g->players);
                t[sizeof(t) - 1] = 0;
                UiText(UI_REGULAR, 12, rx + 90, ry + 35, UI_COL_TEXT3, t, UI_LEFT);
                _snprintf(t, sizeof(t) - 1, Tr(T_TOP_HOURS), (g->minutes + 30) / 60);
                t[sizeof(t) - 1] = 0;
                UiText(UI_BOLD, 15, rx + rw - 40, ry + 24, UI_COL_TEXT, t, UI_RIGHT);
                if (period == 0)
                {
                    if (!g->last)
                    {
                        const float nw = UiTextWidth(UI_BOLD, 9, Tr(T_PIC_NEW)) + 10;
                        UiRoundRect(rx + rw - 8 - nw, ry + 16, nw, 16, 8, D3DCOLOR_ARGB(255, 255, 196, 70), D3DCOLOR_ARGB(255, 255, 196, 70));
                        UiText(UI_BOLD, 9, rx + rw - 8 - nw * 0.5f, ry + 24, D3DCOLOR_ARGB(255, 40, 30, 10), Tr(T_PIC_NEW), UI_CENTER);
                    }
                    else if (g->last != g->place)
                        icon_tri(rx + rw - 20, ry + 24, 10, g->last > g->place ? 0 : 2, g->last > g->place ? ONLINE_GREEN : D3DCOLOR_ARGB(255, 240, 100, 100));
                }
            }
        }
        UiText(UI_REGULAR, 12, lx + lw, y + h - 16, UI_COL_TEXT3, Tr(T_TOP_HOURLY), UI_RIGHT);
        UiScreenFooter(Tr(T_FOOT_TOP));
        UiEnd();
        UiPresent(dev);
    }
    for (k = 0; k < 10; k++)
        if (cover[k]) UiImageRelease(dev, cover[k]);
    return result;
}

#define PLAYERS_TAB_WEEK 2
#define PLAYERS_TAB_RANK 3
static int online_players(IDirect3DDevice9 *dev, int start, int rankOnly)
{
    enum { PT_FRIENDS = 0, PT_ONLINE, PT_WEEK, PT_RANK, PT_GAMES, PT_COUNT };   // PT_WEEK: this week's ranking online, PT_RANK: of all
                                                                               // time, PT_GAMES: the most played games (online_top_games)
    static const int tabLabel[PT_COUNT] = { T_ONLINE_FRIENDS, T_ONLINE_TAB_ONLINE, T_ONLINE_TAB_WEEK, T_ONLINE_TAB_RANK, T_ONLINE_TAB_GAMES };
    static const int tabKind[PT_COUNT] = { ONLINE_LIST_FRIENDS, ONLINE_LIST_USERS, ONLINE_LIST_WEEK, ONLINE_LIST_RANK, ONLINE_LIST_RANK };
    static UiAnim selAnim;
    std::vector<OnlineUser> lists[PT_COUNT], more;
    std::vector<OnlineRoomInfo> rooms;
    int loaded[PT_COUNT] = { 0 }, full[PT_COUNT] = { 0 };
    const int firstTab = rankOnly ? PT_WEEK : 0;
    int tab = rankOnly ? start : PT_FRIENDS, sel = 0, top = 0, k;
    UiInput in;
    recent_load();
    UiInputInit(&in);
    for (;;)
    {
        const float w = UI_WIDTH - 2 * UI_SAFE_X, h = 520, x = UI_SAFE_X, y = 112, lx = x + 26, lw = w - 52, rowH = 82;
        std::vector<OnlineUser> &users = lists[tab];
        int n, nr, rows, recentSel;
        WORD down;
        if (tab == PT_GAMES)
        {
            // The games' tab: its own screen, the same tab bar; it says which tab next.
            const int r = online_top_games(dev, tabLabel + firstTab, PT_COUNT - firstTab, tab - firstTab);
            if (r == 2) return 1;
            if (r < 0) return 0;
            tab = firstTab + r;
            sel = top = 0;
            UiInputInit(&in);
            continue;
        }
        if (!loaded[tab])
        {
            // This tab's players (and, for the friends, the rooms waiting: a friend's own can be joined).
            online_busy(dev, Tr(T_ONLINE_USERS), T_ONLINE_CONNECTING);
            if (!OnlineList(tabKind[tab], 0, &users)) { online_message(dev, Tr(T_ONLINE_USERS), online_error_text()); return 0; }
            if (tab == PT_FRIENDS)
            {
                // Online first.
                size_t a2, b2;
                for (a2 = 1; a2 < users.size(); a2++)
                    for (b2 = a2; b2 > 0 && users[b2].online && !users[b2 - 1].online; b2--) std::swap(users[b2], users[b2 - 1]);
                if (!OnlineRooms(&rooms)) rooms.clear();
            }
            full[tab] = tab != PT_FRIENDS && users.size() == 50;   // a full page: there may be more
            loaded[tab] = 1;
            sel = top = 0;
            UiInputInit(&in);
        }
        n = (int)users.size();
        nr = tab == PT_FRIENDS ? (int)(s_recent.size() < 3 ? s_recent.size() : 3) : 0;
        rows = nr ? 3 : 4;
        recentSel = sel >= n ? sel - n : -1;   // the played-with-lately cards: after the friends
        down = UiInputPoll(&in);
        if (down & (XINPUT_GAMEPAD_B | XINPUT_GAMEPAD_BACK)) { xb_audio_ui_sound(XB_SFX_BACK); return 0; }
        if (down & (XINPUT_GAMEPAD_LEFT_SHOULDER | XINPUT_GAMEPAD_RIGHT_SHOULDER))
        {
            const int tabs = PT_COUNT - firstTab;
            tab = firstTab + (tab - firstTab + ((down & XINPUT_GAMEPAD_RIGHT_SHOULDER) ? 1 : tabs - 1)) % tabs;
            sel = top = 0;
            xb_audio_ui_sound(XB_SFX_TAB);
            continue;
        }
        if (n + nr)
        {
            if (recentSel >= 0 && (down & (XINPUT_GAMEPAD_DPAD_LEFT | XINPUT_GAMEPAD_DPAD_RIGHT)))
            {
                sel = n + (recentSel + ((down & XINPUT_GAMEPAD_DPAD_RIGHT) ? 1 : nr - 1)) % nr;
                xb_audio_ui_sound(XB_SFX_MOVE);
            }
            if (down & XINPUT_GAMEPAD_DPAD_DOWN)
            {
                if (recentSel < 0 && sel == n - 1 && full[tab])
                {
                    // The end of what was read: the next page.
                    online_busy(dev, Tr(T_ONLINE_USERS), T_ONLINE_CONNECTING);
                    full[tab] = OnlineList(tabKind[tab], n, &more) && !more.empty();
                    users.insert(users.end(), more.begin(), more.end());
                    if (more.size() < 50) full[tab] = 0;
                    n = (int)users.size();
                    UiInputInit(&in);
                }
                if (recentSel < 0 && sel + 1 < n + (nr ? 1 : 0)) sel++;
                else if (recentSel < 0) sel = 0;
                xb_audio_ui_sound(XB_SFX_MOVE);
            }
            if (down & XINPUT_GAMEPAD_DPAD_UP)
            {
                if (recentSel >= 0) sel = n ? n - 1 : n;
                else sel = sel > 0 ? sel - 1 : (nr ? n : n - 1);
                xb_audio_ui_sound(XB_SFX_MOVE);
            }
        }
        recentSel = sel >= n ? sel - n : -1;
        {
            // The player selected, and a room of theirs waiting (a friend's: "Join").
            const char *name = recentSel >= 0 ? (recentSel < nr ? s_recent[recentSel].tag.c_str() : "") : n ? users[sel].name : "";
            const int avatar = recentSel >= 0 ? (recentSel < nr ? s_recent[recentSel].avatar : 0) : n ? users[sel].avatar : 0;
            const int isMe = name[0] && !_stricmp(name, OnlineMe()->tag), isFriend = recentSel < 0 && n ? users[sel].isFriend : 0;
            int room = -1;
            for (k = 0; recentSel < 0 && name[0] && k < (int)rooms.size(); k++)
                if (!_stricmp(rooms[k].host, name) && rooms[k].players < rooms[k].max) room = k;
            if (name[0] && (down & XINPUT_GAMEPAD_A))
            {
                xb_audio_ui_sound(XB_SFX_SELECT);
                if (online_stats(dev, name)) return 1;
                UiInputInit(&in);
                continue;
            }
            if (name[0] && !isMe && (down & XINPUT_GAMEPAD_X))
            {
                xb_audio_ui_sound(XB_SFX_SELECT);
                if (online_conversation(dev, name, avatar)) return 1;
                UiInputInit(&in);
                continue;
            }
            if (name[0] && !isMe && (down & XINPUT_GAMEPAD_Y))
            {
                xb_audio_ui_sound(XB_SFX_SELECT);
                if (room >= 0)
                {
                    // Into the friend's room (its password asked when it has one).
                    char pass[ONLINE_ROOM_PASS + 1] = "";
                    if (!rooms[room].locked || online_keyboard(dev, rooms[room].name, Tr(T_ONLINE_PASSWORD_ASK), pass, 1, ONLINE_ROOM_PASS, KBD_NAME))
                    {
                        online_busy(dev, Tr(T_ONLINE_PLAY), T_ONLINE_CONNECTING);
                        if (OnlineRoomJoin(rooms[room].code, pass)) { if (online_lobby(dev, std::string())) return 1; }
                        else online_message(dev, Tr(T_ONLINE_PLAY), online_error_text());
                    }
                    loaded[PT_FRIENDS] = 0;   // the rooms again
                }
                else
                {
                    // A friend, or not any more (asked first).
                    const int add = !isFriend;
                    char how[16] = "";
                    if (isFriend == 1)
                    {
                        const char *labels[2];
                        char q[96];
                        labels[0] = Tr(T_ONLINE_UNFRIEND);
                        labels[1] = Tr(T_ONLINE_KICK_NO);
                        _snprintf(q, sizeof(q) - 1, Tr(T_ONLINE_UNFRIEND_ASK), name);
                        q[sizeof(q) - 1] = 0;
                        if (ChoiceScreen(dev, Tr(T_ONLINE_FRIENDS), q, labels, 2, 1, Tr(T_FOOT_ONLINE), 1) != 0) { UiInputInit(&in); continue; }
                    }
                    online_busy(dev, Tr(T_ONLINE_FRIENDS), T_ONLINE_CONNECTING);
                    if (OnlineFriend(name, add, how, sizeof(how)))
                    {
                        char t[96];
                        xb_audio_ui_sound(add ? XB_SFX_VALUE_UP : XB_SFX_VALUE_DOWN);
                        if (add)
                        {
                            _snprintf(t, sizeof(t) - 1, Tr(strcmp(how, "sent") ? T_ONLINE_NOW_FRIENDS : T_ONLINE_REQUEST_SENT), name);
                            t[sizeof(t) - 1] = 0;
                            online_message(dev, Tr(T_ONLINE_FRIENDS), t);
                        }
                        loaded[PT_FRIENDS] = 0;   // the friends again (and this tab's marks)
                        if (tab != PT_FRIENDS) loaded[tab] = 0;
                    }
                    else xb_audio_ui_sound(XB_SFX_ERROR);
                }
                UiInputInit(&in);
                continue;
            }
            if (recentSel < 0)
            {
                if (sel < top) top = sel;
                if (sel >= top + rows) top = sel - rows + 1;
            }
            dev->Clear(0, NULL, D3DCLEAR_TARGET, UI_COL_BG_BOTTOM, 1.0f, 0);
            online_begin(dev, __FUNCTION__);
            if (rankOnly)
            {
                // the ranking's own: a solid panel (nothing shows through it)
                UiRoundRect(x, y, w, h, 22, D3DCOLOR_ARGB(255, 18, 20, 38), D3DCOLOR_ARGB(255, 14, 16, 30));
                UiRoundRing(x, y, w, h, 22, 2.0f, D3DCOLOR_ARGB(255, 70, 80, 130));
            }
            else hub_frame("", NULL, x, y, w, h);
            UiOnlineLogo(UI_WIDTH * 0.5f, y - 46, 60);
            online_me_corner(x, y, w);
            {
                // The title, the tabs between LB and RB (each with its count), what the tab holds on the right.
                const char *title = Tr(rankOnly ? T_RANK_TITLE : T_ONLINE_USERS);
                const float ix = rankOnly ? 34 : 0;
                float tx = lx + ix + UiTextWidth(UI_BOLD, 28, title) + 30;
                int t2, on = 0;
                char num[48];
                if (rankOnly) menu_icon(UI_ICON_TROPHY, lx + 14, y + 38, D3DCOLOR_ARGB(255, 255, 196, 70));
                UiText(UI_BOLD, 28, lx + ix, y + 38, UI_COL_TEXT, title, UI_LEFT);
                UiRoundRect(tx, y + 26, 38, 24, 12, D3DCOLOR_ARGB(255, 60, 62, 76), D3DCOLOR_ARGB(255, 60, 62, 76));
                UiText(UI_BOLD, 13, tx + 19, y + 38, UI_COL_TEXT2, "LB", UI_CENTER);
                tx += 52;
                for (t2 = firstTab; t2 < PT_COUNT; t2++)
                {
                    const int cur = t2 == tab, cnt = loaded[t2] && t2 < PT_WEEK ? (int)lists[t2].size() : -1;
                    const float lw2 = UiTextWidth(cur ? UI_BOLD : UI_REGULAR, 18, Tr(tabLabel[t2]));
                    float bw;
                    num[0] = 0;
                    if (cnt >= 0) _snprintf(num, sizeof(num), "%d", cnt);
                    bw = lw2 + 36 + (num[0] ? UiTextWidth(UI_BOLD, 13, num) + 22 : 0);
                    if (cur) { UiRoundRect(tx, y + 20, bw, 36, 18, SEL_HI(255), SEL_HI(220)); UiRoundRing(tx, y + 20, bw, 36, 18, 2.0f, D3DCOLOR_ARGB(255, 190, 170, 255)); }
                    else UiRoundRing(tx, y + 20, bw, 36, 18, 1.0f, D3DCOLOR_ARGB(40, 255, 255, 255));
                    UiText(cur ? UI_BOLD : UI_REGULAR, 18, tx + 18, y + 38, cur ? UI_COL_TEXT : UI_COL_TEXT2, Tr(tabLabel[t2]), UI_LEFT);
                    if (num[0])
                    {
                        const float nx = tx + 18 + lw2 + 8, nw = UiTextWidth(UI_BOLD, 13, num) + 14;
                        const D3DCOLOR nc = t2 == PT_FRIENDS ? D3DCOLOR_ARGB(255, 40, 200, 190) : ONLINE_GREEN;
                        UiRoundRect(nx, y + 29, nw, 18, 9, UiAlpha(nc, 0.24f), UiAlpha(nc, 0.24f));
                        UiText(UI_BOLD, 13, nx + nw * 0.5f, y + 38, nc, num, UI_CENTER);
                    }
                    tx += bw + 10;
                }
                UiRoundRect(tx, y + 26, 38, 24, 12, D3DCOLOR_ARGB(255, 60, 62, 76), D3DCOLOR_ARGB(255, 60, 62, 76));
                UiText(UI_BOLD, 13, tx + 19, y + 38, UI_COL_TEXT2, "RB", UI_CENTER);
                if (tab == PT_FRIENDS)
                {
                    for (k = 0; k < n; k++) on += users[k].online != 0;
                    _snprintf(num, sizeof(num) - 1, Tr(T_ONLINE_FRIENDS_SUM), n, on);
                    num[sizeof(num) - 1] = 0;
                    UiText(UI_REGULAR, 15, lx + lw, y + 38, UI_COL_TEXT3, num, UI_RIGHT);
                }
                UiRect(lx, y + 74, lw, 1, UI_COL_LINE);
            }
            if (!n) UiText(UI_REGULAR, 19, lx + lw * 0.5f, y + 150, UI_COL_TEXT3, Tr(T_ONLINE_EMPTY), UI_CENTER);
            for (k = 0; k < rows && top + k < n; k++)
            {
                const OnlineUser *u = &users[top + k];
                const int s1 = top + k == sel, me = !_stricmp(u->name, OnlineMe()->tag), ms = me && OnlineMyMs() ? OnlineMyMs() : u->ms;
                const float ry = y + 94 + k * rowH, cy = ry + 35, ax = lx + (tab >= PT_WEEK ? 82 : 40);
                const D3DCOLOR state = !u->online ? D3DCOLOR_ARGB(255, 90, 92, 105) : u->status[0] ? ONLINE_GREEN : D3DCOLOR_ARGB(255, 40, 200, 190);
                char t[96], fit[96];
                float nw, rx = lx + lw - 16;
                int j, hosts = 0;
                if (s1)
                {
                    UiShadow(lx - 2, ry - 2, lw + 4, 74, 18, 12, SEL_LO(90));
                    UiRoundRect(lx, ry, lw, 70, 14, D3DCOLOR_ARGB(230, 70, 52, 130), D3DCOLOR_ARGB(230, 62, 46, 116));
                    UiRoundRing(lx, ry, lw, 70, 14, 2.0f, D3DCOLOR_ARGB(255, 190, 170, 255));
                }
                else if (rankOnly)
                {
                    // solid rows; this player's ringed
                    UiRoundRect(lx, ry, lw, 70, 14, D3DCOLOR_ARGB(255, 30, 33, 54), D3DCOLOR_ARGB(255, 27, 30, 49));
                    UiRoundRing(lx, ry, lw, 70, 14, me ? 2.0f : 1.0f, me ? D3DCOLOR_ARGB(255, 140, 200, 255) : D3DCOLOR_ARGB(255, 48, 52, 76));
                }
                else
                {
                    UiRoundRect(lx, ry, lw, 70, 14, D3DCOLOR_ARGB(12, 255, 255, 255), D3DCOLOR_ARGB(12, 255, 255, 255));
                    UiRoundRing(lx, ry, lw, 70, 14, 1.0f, D3DCOLOR_ARGB(24, 255, 255, 255));
                }
                if (tab >= PT_WEEK)
                {
                    _snprintf(t, sizeof(t), "%d", u->pos);
                    UiText(UI_BOLD, 22, lx + 44, cy, u->pos <= 3 ? D3DCOLOR_ARGB(255, 255, 205, 70) : UI_COL_TEXT3, t, UI_RIGHT);
                }
                online_avatar(ax, cy, 23, u->avatar, u->name);
                if (!u->online) UiCircle(ax, cy, 23, D3DCOLOR_ARGB(130, 30, 30, 40));   // offline: dimmed
                UiCircle(ax + 16, cy + 16, 7, D3DCOLOR_ARGB(255, 20, 20, 32));
                UiCircle(ax + 16, cy + 16, 5, state);
                nw = UiText(UI_BOLD, 20, ax + 42, cy - 11, u->online || tab >= PT_WEEK ? online_tag_colour(u->name) : UI_COL_TEXT2, u->name, UI_LEFT);
                if (!online_flag(ax + 42 + nw + 12, cy - 11, 15, online_country_index(u->country)))
                    UiText(UI_REGULAR, 13, ax + 42 + nw + 12, cy - 11, UI_COL_TEXT3, u->country, UI_LEFT);
                if (tab >= PT_WEEK && rankOnly && me)
                {
                    const float yw = UiTextWidth(UI_BOLD, 15, Tr(T_RANK_YOU));
                    UiText(UI_BOLD, 15, rx, cy, D3DCOLOR_ARGB(255, 160, 210, 255), Tr(T_RANK_YOU), UI_RIGHT);
                    rx -= yw + 18;
                }
                if (tab >= PT_WEEK) online_time(u->minutes, t, sizeof(t));
                else if (u->online && u->status[0]) { _snprintf(t, sizeof(t) - 1, Tr(T_ONLINE_PLAYING), u->status); t[sizeof(t) - 1] = 0; }
                else _snprintf(t, sizeof(t), "%s", Tr(u->online ? T_ONLINE_ON : T_ONLINE_OFF));
                UiTextFit(UI_REGULAR, 15, 420, t, fit, sizeof(fit));
                UiText(UI_REGULAR, 15, ax + 42, cy + 13, tab >= PT_WEEK ? UI_COL_TEXT2 : u->online ? state : UI_COL_TEXT3, fit, UI_LEFT);
                for (j = 0; tab == PT_FRIENDS && j < (int)rooms.size(); j++)
                    if (!_stricmp(rooms[j].host, u->name) && rooms[j].players < rooms[j].max) hosts = 1;
                if (hosts)
                {
                    // Waiting in a room of theirs: Y joins it.
                    const float bw = UiTextWidth(UI_BOLD, 14, Tr(T_ONLINE_JOIN)) + 30;
                    UiRoundRect(rx - bw, cy - 14, bw, 28, 14, D3DCOLOR_ARGB(50, 80, 210, 120), D3DCOLOR_ARGB(50, 80, 210, 120));
                    UiRoundRing(rx - bw, cy - 14, bw, 28, 14, 1.0f, D3DCOLOR_ARGB(160, 80, 210, 120));
                    UiText(UI_BOLD, 14, rx - bw * 0.5f, cy, ONLINE_GREEN, Tr(T_ONLINE_JOIN), UI_CENTER);
                    rx -= bw + 22;
                }
                if (tab != PT_FRIENDS && u->isFriend && !me)
                {
                    const char *ft = Tr(u->isFriend == 2 ? T_ONLINE_ASKED : T_ONLINE_FRIEND);
                    const float fw = UiTextWidth(UI_BOLD, 13, ft) + 18;
                    UiRoundRect(rx - fw, cy - 11, fw, 22, 11, D3DCOLOR_ARGB(40, 40, 200, 190), D3DCOLOR_ARGB(40, 40, 200, 190));
                    UiText(UI_BOLD, 13, rx - fw * 0.5f, cy, D3DCOLOR_ARGB(255, 40, 200, 190), ft, UI_CENTER);
                    rx -= fw + 22;
                }
                if (u->online && ms > 0 && tab < PT_WEEK)
                {
                    const char *word = Tr(ms < 90 ? T_ONLINE_LINK_GOOD : ms < 160 ? T_ONLINE_LINK_OK : T_ONLINE_LINK_BAD);
                    const float ww = UiTextWidth(UI_BOLD, 15, word);
                    UiText(UI_BOLD, 15, rx, cy, online_ping_colour(ms), word, UI_RIGHT);
                    online_ping_bars(rx - ww - 34, cy, 16, ms);
                }
            }
            if (nr)
            {
                // The players one played with lately (friends or not): A their statistics, Y a friend.
                const float ry = y + 94 + 3 * rowH + 12, cw = (lw - 2 * 14) / 3;
                UiText(UI_BOLD, 16, lx, ry, UI_COL_TEXT2, Tr(T_ONLINE_RECENT), UI_LEFT);
                for (k = 0; k < nr; k++)
                {
                    const float cx0 = lx + k * (cw + 14), cy0 = ry + 18;
                    const int s1 = recentSel == k;
                    char fit[64];
                    if (s1)
                    {
                        UiRoundRect(cx0, cy0, cw, 52, 12, D3DCOLOR_ARGB(230, 70, 52, 130), D3DCOLOR_ARGB(230, 62, 46, 116));
                        UiRoundRing(cx0, cy0, cw, 52, 12, 2.0f, D3DCOLOR_ARGB(255, 190, 170, 255));
                    }
                    else
                    {
                        UiRoundRect(cx0, cy0, cw, 52, 12, D3DCOLOR_ARGB(10, 255, 255, 255), D3DCOLOR_ARGB(10, 255, 255, 255));
                        UiRoundRing(cx0, cy0, cw, 52, 12, 1.0f, D3DCOLOR_ARGB(24, 255, 255, 255));
                    }
                    online_avatar(cx0 + 27, cy0 + 26, 15, s_recent[k].avatar, s_recent[k].tag.c_str());
                    UiText(UI_BOLD, 16, cx0 + 52, cy0 + 18, online_tag_colour(s_recent[k].tag.c_str()), s_recent[k].tag.c_str(), UI_LEFT);
                    UiTextFit(UI_REGULAR, 13, cw - 64, s_recent[k].game.c_str(), fit, sizeof(fit));
                    UiText(UI_REGULAR, 13, cx0 + 52, cy0 + 37, UI_COL_TEXT3, fit, UI_LEFT);
                }
            }
            {
                // The buttons: Y joins the room when there is one, else makes a friend (or not).
                char foot[200];
                _snprintf(foot, sizeof(foot) - 1, "A:%s|X:%s|Y:%s|LB/RB:%s|B:%s", Tr(T_ONLINE_F_PROFILE), Tr(T_ONLINE_F_MESSAGE),
                          Tr(room >= 0 ? T_ONLINE_JOIN : isFriend == 1 ? T_ONLINE_F_REMOVE : T_ONLINE_F_ADD), Tr(T_ONLINE_F_TAB), Tr(T_ONLINE_F_BACK));
                foot[sizeof(foot) - 1] = 0;
                UiScreenFooter(foot);
            }
            online_end();
            UiPresent(dev);
        }
    }
}


// Check for updates: GitHub asked now; a newer release is offered as the ROM list offers it.
static void online_update(IDirect3DDevice9 *dev)
{
    char version[32] = "", text[160];
    int r;
    online_busy(dev, Tr(T_ONLINE_UPDATE), T_ONLINE_CONNECTING);
    r = UpdateCheckNow(H64_VERSION_STRING, version, sizeof(version));
    if (r <= 0)
    {
        _snprintf(text, sizeof(text) - 1, Tr(r < 0 ? T_ONLINE_NO_SERVER : T_ONLINE_UP_TO_DATE), H64_VERSION_STRING);
        text[sizeof(text) - 1] = 0;
        online_message(dev, Tr(T_ONLINE_UPDATE), text);
        return;
    }
    if (!confirm_ask(dev, T_UPDATE_TITLE, T_UPDATE_ASK, T_FOOT_UPDATE)) return;
    views_clear(dev);   // the memory for the download
    ArtPause(1);
    if (update_run(dev, version))
    {
        xb_audio_music_stop();
        XLaunchNewImage("game:\\default.xex", 0);   // the new version
    }
    ArtPause(0);
    online_message(dev, Tr(T_ONLINE_UPDATE), Tr(T_UPDATE_FAILED));
}

static float online_kind_chip(const OnlineRoomInfo *rm, float x, float cy);   // below, with online_have_game
static int online_have_game(const OnlineRoomInfo *rm);
static float online_have_chip(int have, float x, float cy);
static void online_room_head(const OnlineRoomInfo *rm, float x, float cy, float maxW, float size, D3DCOLOR col);
#define ONLINE_ROOM_NAME_SHOWN 16   // a room's name at most (the keyboard's limit: its chips fit after it on its line)

// The ROM of the list whose header has these CRCs (the room's game), its path in *file.
static int online_find_rom(u32 crc1, u32 crc2, std::string *file)
{
    std::vector<RomEntry> roms;
    size_t k;
    scan_roms(&roms);
    for (k = 0; k < roms.size(); k++)
    {
        H64Rom rom;
        if (read_header(roms[k].file.c_str(), &rom))
        {
            const int same = rom.crc1 == crc1 && rom.crc2 == crc2;
            h64_rom_free(&rom);
            if (same) { *file = roms[k].file; return 1; }
        }
    }
    return 0;
}

// A chat line drawn: the avatar, the gamertag in the accent colour, the text after it (cut to fit `w`).
static void online_chat_line(float x, float cy, float w, const OnlineChatLine *m)
{
    float tw;
    const float when = m->when[0] ? UiTextWidth(UI_REGULAR, 14, m->when) + 12 : 0;
    online_avatar(x + 14, cy, 13, m->avatar, m->tag);
    tw = UiText(UI_BOLD, 17, x + 36, cy, UI_COL_ACCENT_HI, m->tag, UI_LEFT);
    RichText(UI_REGULAR, 17, x + 46 + tw, cy, w - 52 - tw - when, 1, UI_COL_TEXT, m->text.c_str(), 1, NULL);
    if (m->when[0]) UiText(UI_REGULAR, 14, x + w, cy, UI_COL_TEXT3, m->when, UI_RIGHT);
}

// A player's colour in the chats and lists: this console's player's lilac, the others' one of seven,
// always the same for a name.
static D3DCOLOR online_tag_colour(const char *tag)
{
    static const D3DCOLOR pal[7] = { D3DCOLOR_ARGB(255, 255, 184, 92), D3DCOLOR_ARGB(255, 110, 214, 150), D3DCOLOR_ARGB(255, 90, 200, 255),
                                     D3DCOLOR_ARGB(255, 255, 130, 170), D3DCOLOR_ARGB(255, 240, 210, 90), D3DCOLOR_ARGB(255, 130, 165, 255),
                                     D3DCOLOR_ARGB(255, 70, 210, 200) };
    unsigned hsh = 5381;
    const char *p;
    if (!_stricmp(tag, OnlineMe()->tag)) return D3DCOLOR_ARGB(255, 190, 165, 255);
    for (p = tag; *p; p++) hsh = hsh * 33 + (unsigned char)tolower((unsigned char)*p);
    return pal[hsh % 7];
}

// A local player's symbol in place of an avatar, r round at (cx, cy): a controller in a ring of its console's
// player's colour, and its number ("P2").
